package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipException;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_getNextZipEntry_TriageGen0Test {

    private static final long LFH_SIG = 0x04034b50L;
    private static final long CFH_SIG = 0x02014b50L;
    private static final long AED_SIG = 0x06054b50L;

    private byte[] createLFH(String name, int method, boolean hasDataDescriptor, long crc, long size, long compressedSize) {
        // Minimal LFH structure calculation
        // Signature (4) + Version (2) + Flags (2) + Method (2) + Time (2) + Mod (2) + CRC (4) + CompSize (4) + UncompSize (4) + NameLen (2) + ExtraLen (2)
        int nameBytesLen = name.getBytes().length;
        int totalSize = 30 + nameBytesLen; 
        if (hasDataDescriptor) {
            totalSize += 12; // CRC (4) + CompSize (4) + UncompSize (4)
        }

        ByteBuffer bb = ByteBuffer.allocate(totalSize).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20); // version made by
        bb.putShort((short) 0);  // flags
        bb.putShort((short) method);
        bb.putShort((short) 0);  // time
        bb.putShort((short) 0);  // mod

        if (!hasDataDescriptor) {
            bb.putInt((int) crc);
            bb.putInt((int) compressedSize);
            bb.putInt((int) size);
        }

        bb.putShort((short) nameBytesLen);
        bb.putShort((short) 0); // extra len
        bb.put(name.getBytes());

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_ClosedOrHitCentralDirectory() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        zis.close();
        Assert.assertNull(zis.getNextZipEntry());

        // Simulate hitCentralDirectory via a mock or by feeding CFH signature
        // Since we can't easily set private field hitCentralDirectory without reflection, 
        // we trigger it by providing CFH signature
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) CFH_SIG);
        ZipArchiveInputStream zis2 = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        Assert.assertNull(zis2.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);
        Assert.assertNull(zis.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_UnexpectedSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0xBAD00000);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        try {
            zis.getNextZipEntry();
            Assert.fail("Should have thrown ZipException");
        } catch (ZipException e) {
            Assert.assertTrue(e.getMessage().contains("Unexpected record signature"));
        }
    }

    @Test
    public void testGetNextZipEntry_Success_Stored() throws IOException {
        byte[] lfh = createLFH("test.txt", 0, false, 1234L, 10L, 5L);
        // Append dummy data for the name and extra field read
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zis = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals("test.txt", entry.getName());
        Assert.assertEquals(0, entry.getMethod());
    }

    @Test
    public void testGetNextZipEntry_Success_DataDescriptor() throws IOException {
        // Manual construction for Data Descriptor
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20);
        bb.putShort((short) 1); // Bit 0: Data Descriptor
        bb.putShort((short) 0); // Method
        bb.putShort((short) 0); // Time
        bb.putShort((short) 0); // Mod
        bb.putShort((short) 4); // Name len
        bb.putShort((short) 0); // Extra len
        bb.put("test".getBytes());

        // Data Descriptor follows the file data in real zip, 
        // but the code reads name and extra first. 
        // The logic in getNextZipEntry for hasDataDescriptor:
        // off += 3 * WORD (skips CRC, CompSize, UncompSize in header)

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        Assert.assertTrue(entry.getGeneralPurposeBit().usesDataDescriptor());
    }

    @Test
    public void testGetNextZipEntry_ConsecutiveEntries() throws IOException {
        byte[] lfh1 = createLFH("a.txt", 0, false, 1L, 1L, 1L);
        byte[] lfh2 = createLFH("b.txt", 0, false, 2L, 2L, 2L);

        byte[] combined = new byte[lfh1.length + lfh2.length];
        System.arraycopy(lfh1, 0, combined, 0, lfh1.length);
        System.arraycopy(lfh2, 0, combined, lfh1.length, lfh2.length);

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(combined));
        Assert.assertNotNull(zis.getNextZipEntry());
        Assert.assertEquals("a.txt", zis.getNextZipEntry().getName()); // This triggers closeEntry()
        Assert.assertNotNull(zis.getNextZipEntry());
        Assert.assertEquals("b.txt", zis.getNextZipEntry().getName());
    }

    @Test
    public void testGetNextZipEntry_UTF8() throws IOException {
        // Setting GP flag bit 11 (Bit 11 is UTF8)
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 20);
        bb.putShort((short) 0x800); // Bit 11 set
        bb.putShort((short) 0);
        bb.putShort((short) 0);
        bb.putShort((short) 0);
        bb.putShort((short) 0);
        bb.putShort((short) 4);
        bb.putShort((short) 0);
        bb.put("test".getBytes());

        ZipArchiveInputStream zis = new ZipArchiveInputStream(new ByteArrayInputStream(bb.array()));
        ZipArchiveEntry entry = zis.getNextZipEntry();
        Assert.assertNotNull(entry);
        // If UTF8 flag is set, it uses UTF8 encoding.
    }
}
